WITH payload AS (SELECT $archive_payload$[{"id":"fe4ec9a9-baaa-5459-a11a-783efe017e9c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -أذية اجلار من خال التسور واإلطاع على عورات منزله -كون املدعى عليه قريبا للمدعي باحلق اخلاص وحرصا على عدم القطيعة بينهم أم ر يلحظ يف تقرير العقوبة -التعزير بأخذ","document_number":"345262","case_number":"33620052","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة مكة املكرمة االطاع على املعاملة الواردة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/5","year":"1434","subject":"إيذاء -أذية اجلار من خال التسور واإلطاع على عورات منزله -كون املدعى عليه قريبا للمدعي باحلق اخلاص وحرصا على عدم القطيعة بينهم أم ر يلحظ يف تقرير العقوبة -التعزير بأخذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك ‪ 345262 :‬تاريخه‪43/10/16 :‬هـ‬\n                          ‫رقم الدعوى‪33620052:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34230922‬تاريخه‪1434/6/5 :‬هـ‬\n\n\n\n      ‫إيــذاء‪ -‬أذيــة اجلــار مــن خــال التســور واإلطــاع علــى عــورات منزلــه‬\n      ‫‪ -‬كــون املدعــى عليــه قريبــا للمدعــي باحلــق اخلــاص وحرصــا علــى‬\n      ‫عــدم القطيعــة بينهــم أمـ ٌـر يلحــظ يف تقريــر العقوبــة‪ -‬التعزيــر بأخــذ‬\n                                                                           ‫التعهــد‬\n\n\n\n      ‫‪ -‬قولــه صلــى اهلل عليــه وســلم يف احلديــث الــذي رواه ابــن عبــاس (لــو‬\n      ‫يعطــى النــاس بدعواهــم الدعــى رجــال دمــاء رجــال وأموالهــم ولكــن‬\n      ‫اليمــن علــى املدعــى عليــه) ويف روايــة البيهقــي (البينــة علــى املدعــي‬\n                                                           ‫واليمــن علــى مــن أنكــر)‬\n      ‫‪ -‬الفقهــاء اتفقــوا علــى جــواز التحليــف يف احلقــوق التــي ليســت مبــال‬\n      ‫وال تــؤول إلــى مــال كأحــكام األبــدان مــن قصــاص وجــروح ووصايــة‬\n      ‫وغيرهــا غيــر أنهــم اختلفــوا يف بعــض املســائل حيــث اســتثنى احلنابلــة‬\n      ‫عشــر مســائل واســتثنى احلنفيــة ســبع مســائل ال يجــوز فيهــا التحليــف‬\n      ‫وليــس ممــا اســتثنى أحــكام األبــدان ومــا يوجــب التعزيــر وذهــب جمهــور‬\n      ‫الشــافعية والصاحبــان مــن احلنفيــة والروايــة عنــد احلنابلــة إلــى‬\n      ‫جــواز التحليــف يف جميــع هــذه األمــور وذهــب املالكيــة إلــى عــدم جــواز‬\n      ‫التحليــف يف النــكاح فقــط‪ .‬ينظــر بدائــع الصنائــع ‪ 227/6‬ومعــن‬\n      ‫احلــكام ‪ 66‬وشــرح اخلرشــي ‪7‬أ‪ 162‬وتبصــرة احلــكام ‪ 197/1‬واحلــاوي‬\n      ‫‪ 148/12‬واملهــذب ‪ 320/2‬وكشــاف القنــاع ‪ 285/4‬واملغنــي ‪272/9‬‬\n‫‪145‬‬\n\f                       ‫ومنتهــى اإلرادات ‪ 33/4‬والطــرق احلكميــة ‪124-110‬‬\n‫‪ -‬قال الشــيخ محمد بن صالح العثيمني رحمه اهلل يف الشــرح املمتع‪:‬‬\n‫‪( 475/15‬قولــه‪ :‬ويســتحلف املنكــر يف كل حــق آلدمــي مــن بيــع وشــراء‬\n‫وإجــارة ووقــف ورهــن وغيــر ذلــك‪ ،‬كل حقــوق اآلدميــن يســتحلف‬\n‫فيهــا املنكــر‪ ،‬ودليــل ذلــك قــول الرســول ص ّلــى اهلل عليــه وسـ ّلم»‪ :‬البينــة‬\n‫علــى املدعــي واليمــن علــى مــن أنكــر» ‪ ،‬ويف احلديــث إشــارة إلــى أن املــراد‬\n‫حقــوق اآلدميــن‪ ،‬ألنــه ليــس هنــاك مــد ٍع ومدعــى عليــه إال يف حقــوق‬\n‫اآلدميــن‪ ،‬واســتثنى املؤلــف فقــال إال النــكاح‪ ،‬والطــاق‪ ،‬والرجعــة‪،‬‬\n‫واإليــاء‪ ،‬وأصــل الــرق‪ ،‬والــوالء‪ ،‬واالســتيالد‪ ،‬والنســب‪ ،‬والقــود‪ ،‬والقــذف‬\n‫هــذه عشــرة اســتثنوها علــى خــاف فيهــا بــن أهــل العلــم‪ ،‬لكــن املذهــب‬\n                                                                 ‫أنهــا مســتثناة»‪.‬‬\n\n\n\n\n‫دعــوى املدعــى العــام واملدعــى اخلــاص ضــد املدعــى عليــه وقــد حضــر‬\n‫ا عنــه حيــث أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه‬      ‫وكي ـ ً‬\n‫بأذيــة جــاره مــن خــال تســوره علــى ســترة منزلهــم وإطالعــه علــى عورات‬\n‫منزلــه‪ ،‬وذلــك إثــر بــاغ اجلهــات املختصــة مفــاده أن املدعــى عليــه يقــوم‬\n‫بالصعــود إلــى ســطح منزلــه املجــاور لســطح منــزل املدعــي ويكشــف‬\n‫علــى أهلــه بالنظــر إليهــم‪ ،‬بالبحــث عن ســوابقه لم يعثر له على ســوابق‪،‬‬\n‫طلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫كمــا طالــب املدعــى اخلــاص تعزيــره ‪ ،‬بعــرض دعــوى املدعــي العــام علــى‬\n‫املدعــى عليــه وكالــة أنكرهــا ودفــع أن صعــود موكلــه كان مرتــن‬\n‫األولــى إلحضــار الفرشــة و الثانيــة إلصــاح اخلــزان‪ ،‬بســؤال املدعــي‬\n\n                                                                                       ‫‪146‬‬\n\f      ‫باحلــق اخلــاص عــن بينتــه علــى أن املدعــي عليــه قــام باالطــاع وكشــف‬\n      ‫عــورات منزلــه ‪ ،‬أحضــر شــاهدا ومت ســماع شــهادته ‪-‬بســؤال املدعــى‬\n      ‫باحلــق اخلــاص واملدعــي العــام هــل لديهمــا زيــادة بينــة؟ قــال املدعــي باحلــق‬\n      ‫اخلــاص نعــم‪ ،‬وأبــرز صــورة للحــدث املدعــى عليــه وهــو يقــوم مبشــاهدة‬\n      ‫بيتــه وجــرى االطــاع عليهــا وعرضهــا علــى املدعــى عليــه وســؤاله عنهــا‬\n      ‫صــادق عليهــا‪ ،‬ودفــع أنــه لــم يكــن يطلــع علــى املنــازل ‪ ،‬نظــر ًا إلقــرار‬\n      ‫املدعــى عليــه بكونــه صعــد إلــى ســطح منزلــه مرتــن مــرة لفتــح‬\n      ‫احملبــس واألخــرى لوضــع الفرشــة ومصادقتــه علــى صحــة الصــورة‬\n      ‫ونفيــه كونــه يطلــع علــى عــورات عمــه‪ ،‬ونظــرا لعــدم البينــة املوصلــة‬\n      ‫لــدي املدعــي العــام واملدعــي باحلــق اخلــاص التــي تديــن املدعــى عليــه وألن‬\n      ‫الفقهــاء اتفقــوا علــى جــواز التحليــف يف احلقــوق التــي ليســت مبــال وال‬\n      ‫تــؤول إلــى مــال لــذا جــرى إفهامــه أن لــه ميــن املدعــى عليــه علــى نفــي‬\n      ‫دعــواه ‪ ،‬أجــاب املدعــي باحلــق اخلــاص أنــه ال يريــد ميــن املدعــى عليــه‬\n      ‫‪ ،‬لــم تثبــت دعــوى املدعــي العــام ضــد املدعــى عليــه ونظــرا ملــا جــاء يف‬\n      ‫شــهادة الشــاهد وملــا قــرره املدعــى عليــه مــن صحــة الصــورة فــإن الشــبهة‬\n      ‫تتجــه نحــوه بقيامــه بأذيــة جــاره مــن خــال تســوره علــى ســترة منزلهــم‬\n      ‫وإطالعــه علــى عــورات منــزل عمــه‪ ،‬وألجــل صلــة الرحــم وحرصــا علــى‬\n      ‫عــدم القطيعــة بينهــم وحلــق الرحــم وملــا يف مثــل هــذه الدعــاوى مــن إثــارة‬\n      ‫الشــحناء والعــداوة بــن األخــوة وزيــادة النفــرة بينهــم ولكــون املدعــى‬\n      ‫عليــه احلــدث صغيــرا يف الســن وملــا يقــع ملــا يف مثــل ســنهم مــن صعــود إلــى‬\n      ‫أعلــى منازلهــم واجللــوس فيهــا لــذا فقــد مت احلكــم بتأديــب املدعــى عليــه‬\n      ‫ألجــل احلــق العــام بأخــذ التعهــد عليــه بعــدم التعــرض لعمــه بالنظــر مــن‬\n      ‫ســطح منزلهــم وكشــف عوراتهــم وجــرى إفهــام املدعــى باحلــق اخلــاص‬\n\n\n‫‪147‬‬\n\f‫بعــدم اســتحقاقه ملــا يدعيــه وأن لــه ميــن املدعــى عليــه علــى نفــي مــا ادعاه‬\n‫متــي طلبهــا ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه واملدعــى باحلــق اخلــاص‬\n‫قــرر املدعــى عليــه القناعــة بــه وقــرر املدعــى باحلــق اخلــاص االعتــراض‬\n‫مــع تقــدمي الئحتــه العتراضيــة عليــه ولــم يتــم أخــذ قناعــة املدعــي العــام‪،‬‬\n          ‫وبعــد رفــع احلكــم حملكمــة اإلســتئناف متــت املصادقــة عليهــا‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة واملكلــف بنظــر قضايــا األحــداث وعليــه وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزئيــة يف محافظــة‬\n‫جدة‪/‬املســاعد برقــم ‪ 33620052‬وتاريــخ ‪ 1433/10/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331855658‬وتاريــخ ‪ 1433/10/21‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق ‪ 1433/12/28‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫بنــاء علــى ورود الالئحــة املقدمــة مــن املدعــي العــام ‪........‬ضــد احلــدث‪/‬‬\n‫‪ )15( ........‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )........‬طالــب و مســلم و متعلــم و غيــر محصــن و مطلــق الســراح‬\n‫بالكفالــة احلضوريــة‪ .‬قائــا يف الئحتــه انــه بتاريــخ ‪1433/8/24‬هـ تقدم‬\n‫املواطــن‪........ /‬ببــاغ الــى الدوريــات األمنيــة يفيــد فيــه بــأن املدعــى عليــه‬\n‫أعــاه يقــوم بالصعــود إلــى ســطح منزلــه املجــاور لســطح منــزل املدعــي‬\n‫ويكشــف علــى أهلــه بالنظــر اليهــم وأنــه ســبق وأن قام بتصويــره باجلوال‬\n‫وهــو علــى تلــك احلــال ‪.‬وباســتجواب املتهــم احلــدث‪ ........ /‬ذكر أنه صعد‬\n‫علــى ســطح منزلهــم مرتــن تقريبـ ًا حيــث أنــه كان يف املــرة األولــى يقــوم‬\n‫بنشــر إلحــدى الفــرش التــي لديهــم باملنــزل (وقــام عمه بتصويــره باجلوال)‬\n\n                                                                                          ‫‪148‬‬\n\f      ‫ويف املــرة الثانيــة صعــد لكــي يفتــح احملبــس الــذي يخــص اخلــزان العلوي‬\n      ‫‪ ،‬وذكــر انــه توجــد مشــاكل بينــه وبــن عمــه بســبب مشــاكل عمــه مــع‬\n      ‫والــده حــول ارث‪ .‬وبســماع شــهادة الشــاهد‪........ /‬أفــاد بأنــه يشــهد بــأن‬\n      ‫اخيــه (‪ )........‬املدعــي قــد اشــتكى اليــه مــن ابــن اخيــه (‪ )........‬حيــث‬\n      ‫ذكــر انــه يقــوم بالصعــود علــى الســطح اخلــاص مبنزلــه وينظــر الــى أهــل‬\n      ‫(‪ )........‬مبنزلهــم املجــاور وأنــه قــد تكــرر ذلــك منــه مرتــن ســابقتني‬\n      ‫وقــد ذهــب إلــى ‪........‬أخــو ‪........‬ولكــن لــم يجــد جتــاوب منــه ‪.‬وقــد جــرى‬\n      ‫االطــاع علــى صــورة محفوظــة بخانــة االســتديو بجــوال املدعــي ويظهــر‬\n      ‫فيهــا املدعــى عليــه وهــو يجلــس علــى ســترة إحــدى البنايــات ومت تدويــن‬\n      ‫محضــر بذلــك ‪.‬وقــد أســفر التحقيــق عــن توجيــه االتهــام إليــه بأذيــة جــاره‬\n      ‫مــن خــال تســوره علــى ســترة منزلهــم واطالعــه علــى عــورات منزلــه ‪،‬‬\n                                 ‫‪-:‬‬                     ‫وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ .1‬مــا جــاء يف أقــوال املدعــى عليــه املدونــة بدفتــر التحقيــق املرفــق لفــه‬\n                                                                                      ‫( )‪.‬‬\n      ‫‪ .2‬مــا جــاء يف شــهادة الشــاهد املنــوه عنهــا واملدونــة بدفتــر التحقيــق‬\n                                                                       ‫املرفــق لفــه ( ) ‪.‬‬\n      ‫‪ .3‬مــا جــاء يف محضــر االطــاع املتضمــن االطــاع علــى صــورة للمتهــم‬\n      ‫وهــو يجلــس علــى الســترة اخلاصــة بالبنايــة واملــدون بدفتــر التحقيــق‬\n      ‫املرفــق لفــه ( ) ‪.‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق‬\n                                                                                  ‫مســجله ‪.‬‬\n      ‫وحيــث أن مــا أقــدم عليــه املتهــم املذكــور فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا لــذا أطلــب اثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫رادعــة لقــاء مــا اســند إليــه) ‪.‬علم ـ ًا بــأن احلــق اخلــاص ال يــزال قائم ـ ًا‬\n\n\n‫‪149‬‬\n\f‫‪(.‬وبــاهلل التوفيــق وبتــاوة الئحــة املدعــي العــام علــى وكيــل املدعــي عليــه‬\n‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬الصــادرة مــن‬\n‫جــدة الوكيــل الشــرعي عــن ‪........‬ســعودي اجلنســية مبوجــب الوكالــة‬\n‫رقــم (‪ )........‬و تاريــخ ‪1433/11/1‬ه ـ و املخولــة لــه حــق املطالبــة و إقامــة‬\n‫الدعــاوي واملرافعــة و املدافعــة و ســماع الدعــاوي و الــرد عليها واإلنكار‬\n‫و اإلقــرار و الصلــح و التنــازل و طلــب اليمــن و رده و االمتنــاع عنــه و‬\n‫إحضــار الشــهود و البينــات و الطعــن فيهــا اإلجابــة و التعديــل و قبــول‬\n‫اإلحــكام و نفيهــا و االعتــراض علــى األحــكام و طلــب االســتئناف و‬\n‫بســؤاله اجلــواب أجــاب قائــا مــا ذكــره املدعــي العــام مــن إن أخــي قــام‬\n‫بالكشــف مــن خــال الســور علــى ســترة املنــزل و اطالعــه علــى عــورات‬\n‫منــزل عمــي فغيــر صحيــح و الصحيــح إن صعــود أخــي للمنــزل كان‬\n‫مرتــن األولــى إلحضــار الفرشــة و الثانيــة إلصــاح اخلــزان هكــذا أجاب‬\n‫ويف هــذه اجللســة حضــر املدعــي باحلــق اخلــاص ‪........‬ســعودي اجلنســية‬\n‫مبوجــب الهويــة الوطنيــة رقــم ‪........‬و الصــادرة مــن جــدة وادعــى قائــا يف‬\n‫حتريــر دعــواه إن املدعــي عليــه ‪........‬ابــن أخــي ‪........‬يقــوم بالصعــود إلــى‬\n‫ســطح منزلهــم و يتطلــع علــى عوراتــي و تكــررت عــدة مــرات و قــد قمــت‬\n‫بالذهــاب لهــم و طلبــت كــف أذاه لكنهــم لــم يســتجيبوا أطلــب احلكــم‬\n‫بتعزيــره شــرعا هــذه دعــواي وبعــرض ذلــك علــى وكيــل املدعــي عليــه‬\n‫مــا ذكــره مــن أنــه كلمنــا فصحيــح و الصــورة لهــا أكثــر مــن ثالثــة أو‬\n‫أربــع أشــهر و بعــد كالمــه لنــا لــم يصعــد إال مرتــن أمــا قبلهــا فــا أعلــم‬\n‫عنــه هكــذا أجــاب و بســؤال املدعــي باحلــق اخلــاص عــن بينتــه علــى أن‬\n‫املدعــي عليــه قــام باالطــاع وكشــف عــورات منزلــه قــال نعــم لــدي بينــه‬\n‫اطلــب إمهالــي إلحضارهــا لــذا جــرى رفــع اجللســة‪ .‬ويف اجللســة املقــررة‬\n\n\n                                                                                        ‫‪150‬‬\n\f      ‫يــوم الثالثــاء املوافــق‪ 1434/01/06‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n      ‫‪ 10‬لســماع دعــوى ‪........‬واملدعــي العــام ضــد ‪........‬وفيهــا حضــر املدعــى‬\n      ‫عليــه ‪........‬ووكليــه الشــرعي ‪........‬وحضــر املدعــي العــام املدعــى باحلــق‬\n      ‫اخلــاص وبســؤاله عمــا مت اســتمهاله ألجلــه قــال أحضــرت معــي للشــهادة‬\n      ‫وأدائهــا املواطــن‪........ /‬وبعــد أن أذنــت لــه شــهد قائــا أشــهد بــاهلل أن‬\n      ‫‪........‬أخــي كلمنــي عــدة مــرات أنــه يتضــرر مــن ‪........‬أنــه يطــل علــى‬\n      ‫منزلــه مــن الســطح وكلمــت ابــن أخــي ‪........‬عــن ذلــك ألجــل أن يكــف‬\n      ‫‪........‬أذاه عنــي وبعدهــا قــام ‪........‬بالشــكوى عليــه هــذا مــا لــدي وبــه‬\n      ‫أشــهد وبســؤاله هــل شــاهدت ‪........‬وهــو يقــوم بالنظــر إلــي فنــاء منــزل‬\n      ‫فهــد أجــاب قائــا لــم أشــاهده وإمنــا صعــدت إلــي ســطح املنــزل وشــاهدت‬\n      ‫‪........‬جالــس يف ســطح املنــزل وكلمتــه عــن ذلــك قــال انــا أطالــع زمالئــي‬\n      ‫مــن ســطح املنــزل ولــم أشــاهد ذلــك هكــذا أجــاب وبعــرض الشــهادة‬\n      ‫علــى ‪........‬يف مجلــس احلكــم قــال شــهادته ال أقــول فيهــا شــيئا فهــو‬\n      ‫عمــي وال أقــول فيــه شــيء لكنــي لــم أصعــد إلــى املنــزل إال مرتــن املــرة‬\n      ‫األولــى ألجــل أن أضــع الفرشــة واملــرة الثانيــة ألجــل فتــح محبــس املــاء‬\n      ‫فقــط هــذه املرتــن بعدمــا كلمنــي عمــي أمــا قبلهــا فقــد كنــت أجلــس‬\n      ‫يف الســطح وال أصعــد فــوق اخلــزان وعندمــا أكــون يف الســطح أقــوم‬\n      ‫بعــض األحيــان باالطــاع علــى الشــارع لكنــي ال أتفــرج علــى املنــازل‬\n      ‫مــن حولــي وإمنــا ملشــاهدة زمالئــي هكــذا أجــاب وبســؤال املدعــى‬\n      ‫باحلــق اخلــاص واملدعــي العــام هــل لديكمــا زيــادة بينــة قــال املدعــي‬\n      ‫باحلــق اخلــاص نعــم الصــورة التــي معــي وجــري اطالعــي عليهــا وعرضهــا‬\n      ‫علــى املدعــى عليــه وســؤاله عنهــا قــال أمــا الصــورة فقــد كانــت عندمــا‬\n      ‫صعدنــا لنضــع الفرشــة أنــا وابــن عمــي وجلســت ارتــاح قليــا كــي‬\n\n\n‫‪151‬‬\n\f‫يرفــع هــو الفرشــة ولــم أكــن اطلــع علــى املنــازل هكــذا اجــاب وبســؤال‬\n‫املدعــى باحلــق اخلــاص واملدعــي العــام هــل لديكمــا زيــادة بينــة قــاال ال‬\n‫وعليــه جــرى اطالعــي علــى أقــوال املدعــى عليــه املرفقــة باملعاملــة لفــة‬\n‫رقــم (‪ )13‬كمــا جــرى اطالعــي علــى شــهادة الشــاهد وعلــى محضــر‬\n‫االطــاع علــى الصــورة املرفقــة باملعاملــة لفــة رقــم (‪ )13‬فودتهــا طبــق‬\n‫مــا ذكــره املدعــي العــام وعليــه وبنــاء علــى مــا تقــدم مــن الدعــوي‬\n‫وجوابهــا وإلقــرار املدعــى عليــه بكونــه صعــد إلــى ســطح منزلــه مرتــن‬\n‫مــرة لفتــح احملبــس واألخــرى لوضــع الفرشــة ومصادقتــه علــى صحــة‬\n‫الصــورة ونفيــه كونــه يطلــع علــى عــورات عمــه وإمنــا كان ينتظــر ابــن‬\n‫عمــه ليرفــع الفرشــة ونظــرا لعــدم البينــة املوصلــة لــدي املدعــي العــام‬\n‫واملدعــي باحلــق اخلــاص التــي تديــن املدعــى عليــه ولعمــوم قولــه صلــى‬\n‫اهلل عليــه وســلم يف احلديــث الــذي رواه ابــن عبــاس (لــو يعطــى النــاس‬\n‫بدعواهــم الدعــى رجــال دمــاء رجــال وأموالهــم ولكــن اليمــن علــى‬\n‫املدعــى عليــه) ويف روايــة البيهقــي (البينــة علــى املدعــي واليمــن علــى‬\n‫مــن أنكــر) متفــق عليــه ومبــا أن الفقهــاء اتفقــوا علــى جــواز التحليــف‬\n‫يف احلقــوق التــي ليســت مبــال وال تــؤول إلــى مــال كأحــكام األبــدان مــن‬\n‫قصــاص وجــروح ووصايــة وغيرهــا غيــر أنهــم اختلفــوا يف بعــض املســائل‬\n‫حيــث اســتثنى احلنابلــة عشــر مســائل واســتثنى احلنفيــة ســبع مســائل ال‬\n‫يجــوز فيهــا التحليــف وليــس ممــا اســتثنى أحــكام األبــدان ومــا يوجــب‬\n‫التعزيــر وذهــب جمهــور الشــافعية والصاحبــان مــن احلنفيــة والروايــة عنــد‬\n‫احلنابلــة إلــى جــواز التحليــف يف جميــع هــذه األمــور وذهــب املالكيــة إلــى‬\n‫عــدم جــواز التحليــف يف النــكاح فقــط ينظــر بدائــع الصنائــع ‪227/6‬‬\n‫ومعــن احلــكام ‪ 66‬وشــرح اخلرشــي ‪7‬أ‪ 162‬وتبصــرة احلــكام ‪197/1‬‬\n\n\n                                                                                     ‫‪152‬‬\n\f      ‫واحلــاوي ‪ 148/12‬واملهــذب ‪ 320/2‬وكشــاف القنــاع ‪ 285/4‬واملغنــي‬\n      ‫‪ 272/9‬ومنتهــى اإلرادات ‪ 33/4‬والطــرق احلكميــة ‪ 124-110‬وجــاء يف‬\n      ‫الشــرح املمتــع للشــيخ محمــد بــن صالــح العثيمــن رحمــه اهلل ‪475/15‬‬\n      ‫(قولــه‪ :‬ويســتحلف املنكــر يف كل حــق آلدمــي‪ ،‬مــن بيــع وشــراء‬\n      ‫وإجــارة ووقــف ورهــن وغيــر ذلــك‪ ،‬كل حقــوق اآلدميــن يســتحلف فيهــا‬\n      ‫املنكــر‪ ،‬ودليــل ذلــك قــول الرســول ص ّلــى اهلل عليــه وسـلّم‪ :‬البينــة علــى‬\n      ‫املدعــي واليمــن علــى مــن أنكــر ‪ ،‬ويف احلديــث إشــارة إلــى أن املــراد‬\n      ‫ـدع ومدعــى عليــه إال يف حقــوق‬  ‫حقــوق اآلدميــن‪ ،‬ألنــه ليــس هنــاك مـ ٍ‬\n      ‫اآلدميــن‪ ،‬واســتثنى املؤلــف فقــال إال النــكاح‪ ،‬والطــاق‪ ،‬والرجعــة‪،‬‬\n      ‫واإليــاء‪ ،‬وأصــل الــرق‪ ،‬والــوالء‪ ،‬واالســتيالد‪ ،‬والنســب‪ ،‬والقــود‪،‬‬\n      ‫والقــذف‪ ،‬هــذه عشــرة اســتثنوها علــى خــاف فيهــا بــن أهــل العلــم‪،‬‬\n      ‫لكــن املذهــب أنهــا مســتثناة ومبــا أن املدعــى باحلــق اخلــاص ليــس لديــه‬\n      ‫بينــة موصلــة لــذا أفهمتــه بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه‬\n      ‫قــال ال أريــد ميينــه ومبــا ان املدعــى العــام ليــس لديــه بينــة موصلــة علــى‬\n      ‫مــا ادعــاه أيضــا لــذا وبنــاء عليــه لــم تثبــت لــدي دعــوي املدعــي العــام‬\n      ‫ضــد املدعــى عليــه إال أن الشــبهة تتجــه نحــوه بقيامــه بأذيــة جــارة مــن‬\n      ‫خــال تســوره علــى ســترة منزلهــم واطالعــه علــى عــورات منــزل عمــه‬\n      ‫وذلــك نظــرا ملــا جــاء يف شــهادة الشــاهد وملــا قــرره املدعــى عليــه مــن‬\n      ‫صحــه الصــورة وألجــل صلــه الرحــم وحرصــا علــى عــدم القطيعــة بينهــم‬\n      ‫وحلــق الرحــم وملــا يف مثــل هــذه الدعــاوى مــن إثــارة الشــحناء والعــداوة‬\n      ‫بــن األخــوة وزيــادة النفــرة بينهــم ولكــون املدعــى عليــه احلــدث ‪........‬‬\n      ‫صغيــرا يف الســن وملــا يقــع ملــا يف مثــل ســنهم مــن صعــود إلــى أعلــى‬\n      ‫منازلهــم واجللــوس فيهــا لــذا فقــد قــررت تأديــب املدعــى عليــه ألجــل‬\n\n\n‫‪153‬‬\n\f‫احلــق العــام بأخــذ التعهــد عليــه بعــدم التعــرض لعمــه بالنظــر مــن ســطح‬\n‫منزلهــم وكشــف عوراتهــم وذلــك ألجــل احلــق العــام وأفهمــت املدعــى‬\n‫باحلــق اخلــاص بعــدم اســتحقاقه ملــا يدعيــه وأن لــه ميــن املدعــى عليــه‬\n‫علــى نفــي مــا ادعــاه حتــى طلبهــا وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى املدعــى عليــه واملدعــى باحلــق اخلــاص قــرر املدعــى عليــه القناعــة بــه‬\n‫وقــررا املدعــى باحلــق اخلــاص االعتــراض مــع تقــدمي الئحتــه االعتراضيــة‬\n‫عليــه فأهمتــه باحلضــور يــوم األربعــاء املوافــق ‪1434/1/14‬ه ـ الســتالم‬\n‫نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يومــا‬\n‫اعتبــار مــن التاريــخ املشــار إليــه فــإن مضــت املــدة ولــم يســتلم نســخه مــن‬\n‫احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان حقــه يف تقــدمي الئحــة‬\n‫االعتــراض يكــون ســاقطا ولــم يتــم أخــذ قناعــة املدعــي العــام حســب‬\n‫التعليمــات وجــري النطــق باحلكــم يــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ‬\n‫الســاعة ‪ 10 : 30‬وبــه أقفلــت اجللســة الســاعة ‪ 10 : 30‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1434/01/06‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n‫بعــده وبعــد فلــدي أن ‪........‬القاضــي باحملكمــة اجلزائيــة بجــدة ففــي يــوم‬\n‫الســبت املوافــق ‪1434/02/09‬ه ـ وبعــد ورود الالئحــة االعتراضيــة مــن‬\n‫املدعــي باحلــق اخلــاص ‪........‬ضــد ‪........‬واملكونــة مــن صفحتــن وبعــد‬\n‫االطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وقــررت رفــع‬\n‫املعاملــة مــع القــرار وصــورة ضبطــه والالئحــة االعتراضيــة حملكمــة‬\n‫االســتئناف مبكــة املكرمــة لتدقيــق احلكــم كاملتبــع وعليــه حصــل‬\n‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أجمعــن حــرر يف ‪1434/02/09‬ه ـ احلمــد هلل وحــده والصــاة‬\n\n\n                                                                                        ‫‪154‬‬\n\f      ‫والســام علــى رســول اهلل ‪ ...‬وبعــد‪ -:‬فقــد جــرى منــا نحــن قضــاة الدائرة‬\n      ‫اجلزائيــة الســابعة يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n      ‫االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n      ‫بجــدة برقــم ‪ 33/1855658‬وتاريــخ ‪1434/5/14‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪........ /‬القاضــي باحملكمــة اجلزائيــة بجــدة‬\n      ‫برقــم ‪ 345262‬وتاريــخ ‪1434/1/6‬ه ـ احملكــوم فيــه مبــا دون بباطــن‬\n      ‫القــرار ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد احلــدث‪(........ /‬العمــر‪15‬‬\n      ‫ســعودي اجلنســية) املتهــم يف أذيــة اجليــران ‪ ،‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل‬\n            ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪155‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":145,"source_page_end":155,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5c319225883749d8ed9f3a0ea232508223fbd438ec24b34dab14ca35a64d40ec","normalized_text_hash":"36edec248038286d231e816ec0b934f2d84d937f038c1c5e6e174a1d04148565","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p145-345262"},{"id":"7ade8fd8-33f7-5d1b-b213-b2d159410a0d","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -الفرق بن ضرب التأديب وضرب التشفي واإليذاء -اإلدانة باإلقرار -تخفيف العقوبة خللو سجل املدعى عليه من السوابق اجلنائية ولكبر سنه -تعزير الزوج لقاء ضربه لزوجته بالسجن.","document_number":"3456328","case_number":"33659760","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة البدائع الشيخ","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/4","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -الفرق بن ضرب التأديب وضرب التشفي واإليذاء -اإلدانة باإلقرار -تخفيف العقوبة خللو سجل املدعى عليه من السوابق اجلنائية ولكبر سنه -تعزير الزوج لقاء ضربه لزوجته بالسجن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك ‪ 3456328 :‬تاريخه‪1434/3/4 :‬هـ‬\n                          ‫رقم الدعوى‪33659760:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34167032‬تاريخه‪1434/3/21 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬الفــرق بــن ضــرب التأديــب‬\n      ‫وضــرب التشــفي واإليــذاء ‪ -‬اإلدانــة باإلقــرار ‪ -‬تخفيــف العقوبــة خللــو‬\n      ‫ســجل املدعــى عليــه مــن الســوابق اجلنائيــة ولكبــر ســنه ‪ -‬تعزيــر الــزوج‬\n                                                  ‫لقــاء ضربــه لزوجتــه بالســجن‪.‬‬\n\n\n\n\n                                   ‫‪-1‬قول اهلل تعالى « وعاشروهن باملعروف «‪.‬‬\n      ‫‪ -2‬عــن جابــر رضــي اهلل عنــه‪ :‬أن النبــي صلــى اهلل عليــه وســلم قــال‬\n      ‫‪ « :‬اتقــوا اهلل يف النســاء فإنكــم أخذمتوهــن بأمــان اهلل واســتحللتم‬\n      ‫فروجهــن بكلمــة اهلل ‪ ،‬ولكــم عليهــن أال يوطئــن فرشــكم أحــدا تكرهونــه‬\n                 ‫فــإن فعلــن فاضربوهــن ضربــا غيــر مبــرح » أخرجــه مســلم‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام للمدعــى عليــه لقيامــه باالعتــداء علــى زوجتــه‬\n      ‫بالضــرب وخنقهــا بيــده والتســبب يف إصابتهــا بســحجات يف العنــق ‪،‬‬\n      ‫وطلــب إثبــات مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة‪ ،‬أقــر املدعــى‬\n      ‫عليــه بالدعــوى إال أنــه دفــع بــأن مــا جــاء يف الئحــة االدعــاء العــام مبالــغ‬\n      ‫فيــه حيــث حصــل خــاف بينــه وبــن زوجتــه تطــور إلــى أن تلفظــت عليــه‬\n      ‫بألفــاظ نابيــة وســيئة ويف حلظــة غضــب قبــض عليهــا بيــده اليســرى مــن‬\n\n‫‪177‬‬\n\f‫عنقهــا وصفعهــا علــى وجههــا بيــده اليمنــى فقــط ثــم ذهبــت لبيــت أهلهــا‬\n‫ال يظــن بــأن ضربتــه أحدثــت فيهــا تلــك اإلصابــة وقــرر بأنهــا ال زالــت يف‬\n‫ذمتــه‪ ،‬باالطــاع علــى التقريــر الطبــي املتضمــن وجــود ســحجات بالعنــق‬\n‫ـاء علــى‬\n        ‫وأن اآللــة املســتعملة غيــر حــادة ومــدة الشــفاء يومــان فقــط‪ ،‬بنـ ً‬\n‫مــا تقــدم ‪ ،‬وألن الضــرب الــذي صــدر مــن الــزوج ليــس ضــرب تأديــب بــل‬\n‫ضــرب إتــاف وتشــفي ‪ ،‬لذلــك كلــه فقــد ثبــت لــدى احملكمــة إدانــة‬\n‫املدعــى عليــه باالعتــداء علــى زوجتــه وخللــو ســجله مــن الســوابق ولكبــر‬\n‫ســنه لذلــك كلــه فقــد قــررت تعزيــر املدعــى عليــه بالســجن خمســة أيــام‬\n‫وبذلــك حكمــت‪ ،‬قــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي‬\n‫العــام وطلــب تدقيقــه بــدون الئحــة‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪........‬قاضــي محكمــة البدائــع العامــة وبنــاء علــى املعاملــة الــواردة‬\n‫الينــا مــن هيئــة التحقيــق واالدعــاء العــام برقــم ه ـ ص ‪1104 /02 / 11‬‬\n‫يف ‪1433/11/15‬ه ـ عليــه ففــي هــذا اليــوم االربعــاء ‪1434/3/4‬ه ـ ويف‬\n‫متــام الســاعة الثامنــة فتحــت اجللســة وفيهــا حضــر املدعــي العــام ‪........‬‬\n‫وادعــى علــى احلاضــر معــه ‪........‬ســعودي بالســجل املدنــي رقــم ‪........‬‬\n‫قائــا يف تقريــر دعــواه إنــه بتاريــخ ‪1433/9/13‬ه ـ ‪ ........‬نازحــة مبوجــب‬\n‫البطاقــة رقــم ‪........‬ببــاغ ضــد زوجهــا املدعــى عليــه تفيــد فيــه بأنــه‬\n‫ا وذلــك بخنقهــا‬   ‫قــام بضربهــا البارحــة يف الســاعة الثانيــة والربــع لي ـ ً‬\n‫يف رقبتهــا بواســطة يــده وضربها(كفــا) علــى وجههــا‪ ،‬وبســماع أقوالــه‬\n\n                                                                                     ‫‪178‬‬\n\f      ‫األوليــة أفــاد بقيامــه بضربهــا كفــا علــى وجههــا‪ ،‬وباســتجوابه اعتــرف‬\n      ‫بضربهــا بواســطة يــده ‪ ،‬وقــد أثبــت التقريــر الطبــي الصــادر مــن القطــاع‬\n      ‫الصحــي مبحافظــة ‪........‬برقــم ‪........‬وتاريــخ ‪1433/9/16‬ه ـ بــأن املجنــي‬\n      ‫عليهــا يوجــد بهــا ســحجات بالعنــق وحالتهــا مســتقرة ومــدة الشــفاء‬\n      ‫يومــان مالــم حتــدث مضاعفــات‪ ،‬وانتهــى التحقيــق الــى اتهــام ‪........ /‬‬\n      ‫ســعودي اجلنســية باالعتــداء بالضــرب علــى زوجتــه وخنقهــا بواســطة يــده‬\n      ‫والتســبب يف إصابتهــا اإلصابــة املوضحــة يف التقريــر الطبــي املنــوه عنــه‪،‬‬\n      ‫وذلــك لألدل ــة والقرائــن التاليــة‪ -1:‬اعترافــه املنــوه عنــه أعــاه املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )1‬مــن ملــف التحقيــق املرفــق لفــه (‪-2.)14‬ســماع‬\n      ‫أقوالــه األوليــة املدونــة علــى الصفحــة رقــم (‪ )4‬مــن ملــف االســتدالل‬\n      ‫املرفــق لفــة رقــم (‪ -2.)1‬مــا جــاء يف التقريــر الطبــي املنــوه عنــه املرفــق‬\n      ‫لفــة رقــم (‪ .)13‬وبالبحــث عــن ســوابقه تبــن خلــو ســجله مــن الســوابق‬\n      ‫‪ ،‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا واســتناد ًا للمــادة (‪ )128-126‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫اطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‪،‬‬\n      ‫علمــا أن احلــق اخلــاص الزال قائمــا‪ ،‬وبســؤال املدعــى عليــه عــن دعــوى‬\n      ‫املدعــي العــام مــا جــاء يف الدعــوى صحيــح إال أنــه مبالــغ فيــه فقــد حصــل‬\n      ‫خــاف بينــي وبــن زوجتــي بســبب خروجهــا عــن طاعتــي تطــور الــى أن‬\n      ‫تلفظــت علــي بألفــاظ نابيــة وســيئة ويف حلظــة غضــب قبضــت عليها بيدي‬\n      ‫اليســرى مــن عنقهــا و لطمتهــا كفــا علــى وجههــا بيــدي اليمنــى فقــط‬\n      ‫وبعــد ذلــك ذهبــت مــع أهلهــا وأظنهــا راجعــت املستشــفى لكــي تســيء‬\n      ‫إلــي وال أظــن ان ضربــي لهــا قــد أحــدث إصابــة تســتدعي مــدة للشــفاء‪،‬‬\n      ‫التــي حلقــت باملدعيــة علمــا بــأن زوجتــي التــي التــزال يف ذمتــي هداهــا‬\n\n\n‫‪179‬‬\n\f‫اهلل كثيــرا مــا تســيء إلــي وتخــرج عــن طاعتــي هــذه اجابتــي كمــا‬\n‫جــرى منــي االطــاع علــى التقريــر الطبــي يف حــق زوجــة املدعــى عليــه‬\n‫‪........‬املشــار إليــه يف الدعــوى واملتضمــن وجــود ســحجات بالعنــق واآللــة‬\n‫املســتخدمة غيــر حــادة ومــدة الشــفاء يومــان فقــط فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واالجابــة وملصادقــة املدعــى عليــه علــى الدعــوى وملــا جــاء‬\n‫يف التقريــر الطبــي بشــأن زوجــة املدعــى عليــه وحيــث أن للــزوج تأديــب‬\n‫زوجتــه عنــد خروجهــا عــن طاعتــه بالضــرب الغيــر مبــرح وغيــر مؤثــر‬\n‫الســيما مــع الوجــه وقــد قــال اهلل تعالــى (( وعاشــروهن باملعــروف ))‬\n‫ولقولــه صلــى اهلل عليــه وســلم ( اتقــو اهلل يف النســاء فإنكــم أخذمتوهــن‬\n‫بأمــان اهلل واســتحللتم فروجهــن بكلمــة اهلل ولكــم عليهــن أال يوطئــن‬\n‫فرشــكم أحــدا تكرهونــه فــإن فعلــن فاضربوهــن ضربــا غيــر مبــرح‬\n‫) وحيــث أن الضــرب الــذي صــدر مــن الــزوج ليــس ضــرب تأديــب وإمنــا‬\n‫ضــرب إتــاف وتشــفي لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه‬\n‫‪........‬باإلعتــداء علــى زوجتــه وضربهــا ضربــا مبرحــا بخنقهــا وضربهــا‬\n‫كفــا علــى وجههــا والتســبب يف اصابتهــا االصابــة املوضحــة يف التقريــر‬\n‫الطبــي وخللــو ســجل املدعــى عليــه مــن الســوابق اجلنائيــة ولكونــه رجــا‬\n‫كبيــرا يظهــر عليــه الوقــار والصــدق لذلــك كلــه فقــد قــررت تعزيــر‬\n‫املدعــى عليــه بالســجن ملــدة خمســة أيــام وبذلــك حكمــت وبعرضــه علــى‬\n‫الطرفــن قــرر املدعــى عليــه القناعــة والرضــا بــه بخــاف املدعــي العــام‬\n‫فقــد قــرر اعتراضــه بــدون الئحــة وعليــه حصــل التوقيــع مــن اجلميــع يف‬\n‫متــام الســاعة التاســعة وبــه حــرر يف ‪1434/3/4‬ه ـ وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وعلــى الــه وصحبــه أجمعــن ‪ .‬احلمــد هلل وحــده وبعــد ‪ ...‬فقــد‬\n‫اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق القضايــا اجلزائيــة مبحكمــة‬\n\n\n                                                                                    ‫‪180‬‬\n\f      ‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة البدائــع الشــيخ‪ ......../‬برقــم وتاريــخ‬\n      ‫‪1434/3/10‬هــ؛ واملقيــدة لدينــا برقــم وتاريــخ ‪1434/3/11‬هــ؛ املرفــق‬\n      ‫بــه القــرار رقــم ‪ 3456328‬وتاريــخ ‪1434/3/4‬هــ؛ الصــادر مــن فضيلتــه‬\n      ‫؛ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ،........ /‬التهامــه باالعتــداء علــى‬\n      ‫زوجتــه ؛ وقــد تضمــن القــرار حكــم فضيلتــه بســجن املدعــي عليــه علــى‬\n      ‫النحــو املفصــل فيــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫ولقناعــة املدعــى عليــه قررنــا املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪،‬‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪،،،،‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":177,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7a2a850bc8557224b7756f4cbb033eb8e39513cf799cdf0bea11e8bf599e623a","normalized_text_hash":"588268ee9fc603f7656c1ecdd0645bbbe8147337ca587b94b7c88ca267180eef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p177-3456328"},{"id":"fee227d8-5e3c-5e47-9ab6-680ba43d0f1d","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -سرقة -سرقة ماكنيه كهربائية -تستر املدعى عليه على شركاءه -إنكار دعوى -عدم وجود البينة املوصلة- ضعف القرائن -عدم وجود سوابق قضائية -عدم ثبوت إدانة- صرف نظرعن الدعوى.","document_number":"33469364","case_number":"33671988","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/29","year":"1434","subject":"اعتداء -ضرب -سرقة -سرقة ماكنيه كهربائية -تستر املدعى عليه على شركاءه -إنكار دعوى -عدم وجود البينة املوصلة- ضعف القرائن -عدم وجود سوابق قضائية -عدم ثبوت إدانة- صرف نظرعن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33469364:‬تاريخه‪1433/11/29 :‬هـ‬\n                    ‫رقم الدعوى‪33671988:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3443838‬تاريخه‪1434/03/29:‬هـ‬\n\n\n\n‫اعتــداء‪ -‬ضــرب ‪ -‬ســرقة ‪ -‬ســرقة ماكنيــه كهربائيــة‪ -‬تســتر املدعــى‬\n‫عليــه علــى شــركاءه ‪ -‬إنــكار دعــوى‪ -‬عــدم وجــود البينــة املوصلــة‪-‬‬\n‫ضعــف القرائــن ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬عــدم ثبــوت إدانــة‪-‬‬\n                                               ‫صــرف نظرعــن الدعــوى‪.‬‬\n\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                     ‫أنكــر)‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى العامــة ضــد مقيــم باالعتــداء علــى أحد الوافدين وســرقة‬\n‫ماطــور كهربائــي والتســتر علــى شــركائه يف اجلرمية‪،‬وطلــب املدعــي‬\n‫العــام إثبــات مــا أســند إليــه واحلكــم بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى‬\n‫املدعــى عليــه بعــد بــاغ مــن أحــد الوافديــن يفيــد بتعرضــه للضــرب مــن‬\n‫قبــل أربعــة أشــخاص وســرقة ماطــور كهربائــي وقــدم أربعــة أرقــام مــن‬\n‫لوحــة ســيارة فقــط بــدون أحــرف وقــد انطبقــت األرقام على لوحة ســيارة‬\n‫املدعــى عليهــم ‪،‬أنكــر املدعــى عليــه الدعوى‪،‬تبــن عــدم وجــود بينــة‬\n‫موصلــة للمدعــى العام‪،‬لــم تثبــت إدانــة املدعــى عليــه‪ ،‬صــرف النظــر عــن‬\n                   ‫الدعــوى‪،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n                                                                                    ‫‪182‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n      ‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعرعــر برقــم ‪ 33671988‬وتاريــخ ‪ 1433/11/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332094953‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n      ‫‪ 09‬وفيهــا قــدم املدعــي العــام ‪ .....‬الئحتــه ضــد ‪ .... /‬ســوري اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم (‪ )......‬والتــي جــاء فيهــا مــا نصــه (فأنــه بتاريــخ‬\n      ‫‪1433/9/20‬ه ـ تقــدم الوافــد ‪ ..... /‬باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم (‪ ).....‬ببــاغ مفيــد ًا عــن تعرضــه العتــداء مــن قبــل أربعــة‬\n      ‫أشــخاص وســرقة ماطــور كهربائــي وباالنتقــال واملعاينــة تبــن أن املوقــع‬\n      ‫عبــارة عــن حــوش مســور ولــه بوابــة علــى طريــق طريــف يف الصناعيــة‬\n      ‫اجلديــدة ويوجــد بــه غرفتــان علــى اليمــن ومبنــى حتــت اإلنشــاء وتبــن أن‬\n      ‫موقــع املاطــور يقــع بالقــرب مــن الســور مــن جهــة الشــمال ولــم يالحــظ‬\n      ‫أي آثــار وبضبــط إفــادة املدعــي ‪..... /‬أفــاد بأنــه أثنــاء تواجــده يف حــوش‬\n      ‫صيانــة إدارة الدفــاع املدنــي بالصناعيــة اجلديــدة ســمع بــاب احلــوش‬\n      ‫يطــرق وعنــد قيامــه بفتــح البــاب وجــد أربعــة أشــخاص فقامــوا مبســكه‬\n      ‫ووضعــه يف ســيارتهم وهــي مــن نــوع داتســون غمــاره لونهــا أبيــض رقــم‬\n      ‫اللوحــة (‪ )....‬واألحــرف غيــر معروفــة لديــه وأفــاد بأنهــم يلبســون (بناطيل‬\n      ‫جينز) لونها أزرق وال يســتطيع حتديد جنســياتهم وأنه يســتطيع التعرف‬\n      ‫عليهــم وبرصــد الســيارات التــي حتمــل رقــم اللوحــة واملواصفــات مــن قبل‬\n      ‫مأمــور النهايــة الطرفيــة ومســاعد ضابــط اخلفــر تبــن وجــود ســيارة يف‬\n\n‫‪183‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":182,"source_page_end":183,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"494b779485eb5cc6bcd61c3f5cf65e2593323bc8d30ea77c894e061513347657","normalized_text_hash":"2c07acbdfe2130039b745dbbf735db91ce7b1c40d7114441f7284eee825f30b3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p182-33469364"},{"id":"4ca256ab-ed64-5d36-b4c3-15517c76e3a7","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -إتاف مال عام -إتاف سيارة الشرطة -مقاومة قوات الشرطة -إنكار املدعى عليه القصد -وجود سابقة مشابهة - التعزير بالسجن واجللد -تعزير للشبهة .","document_number":"3463079","case_number":"33689202","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/16","year":"1434","subject":"اعتداء -إتاف مال عام -إتاف سيارة الشرطة -مقاومة قوات الشرطة -إنكار املدعى عليه القصد -وجود سابقة مشابهة - التعزير بالسجن واجللد -تعزير للشبهة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3463079 :‬تاريخه‪1434/3/16 :‬هـ‬\n                   ‫رقم الدعوى‪33689202:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34206018‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬إتــاف مــال عــام ‪ -‬إتــاف ســيارة الشــرطة ‪ -‬مقاومــة قــوات‬\n‫الشــرطة ‪ -‬إنــكار املدعــى عليــه القصــد ‪ -‬وجــود ســابقة مشــابهة ‪-‬‬\n                       ‫التعزيــر بالســجن واجللــد ‪ -‬تعزيــر للشــبهة ‪.‬‬\n\n\n\n\n                                        ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العــام علــى املدعى عليــه باالعتداء‬\n‫علــى رجــال األمــن بإحلــاق الضــرر مبركبتهمــا وطلــب إثبــات مــا أســند‬\n‫إليــه وإيقــاع العقوبــة التعزيريــة عليــه حيــث جــرى محاولــة اســتيقافه مــن‬\n‫قبــل الدوريــة األمنيــة للتحقــق مــن حالــه فقــام بصــدم ســيارة الدوريــة‬\n‫والذ بالفــرار‪ ،‬أنكــر املدعــى عليــه التهمــة ودفــع بــأن صدمــه لســيارة‬\n‫الدوريــة كان حادث ـ ًا مروري ـ ًا عادي ـ ًا ولــم يكــن بقصــد منــه ‪ ،‬طلبــت‬\n‫البينــة مــن املدعــي العــام قــرر بــأن بينتــه هروبــه مــن الدوريــة األمنيــة ومــا‬\n‫جــاء يف محضــر تنفيــذ املهمــة ومحضــر إثبــات احلالــة ويطلــب الرجــوع‬\n‫إليهــا‪ ،‬مبواجهــة املدعــى عليــه ببينــات املدعــي العــام قــرر بــأن مــا جــاء‬\n‫فيهــا صحيــح ودفــع بــأن الصــدم كان مــن غيــر قصــد ‪ ،‬وبعــد قفــل‬\n‫بــاب املرافعــة وســماع الدعــوى واإلجابــة واالطــاع علــى أوراق املعاملــة‬\n\n                                                                                            ‫‪188‬‬\n\f      ‫وإلقــرار املدعــى عليــه بالصــدم وإنــكاره القصــد ‪ ،‬ولعــدم قيــام البينــة‬\n      ‫الكافيــة إلدانــة املدعــى عليــه ‪ ،‬ولوجــود ســابقة إطــاق نــار علــى‬\n      ‫املدعــى عليــه ‪ ،‬ولهروبــه بعــد الصــدم ‪ ،‬وملجمــوع مــا تقــدم قــررت‬\n      ‫احملكمــة عــدم ثبــوت إدانــة املدعــى عليــه باالعتــداء علــى رجــال األمــن‬\n      ‫باإلضــرار مبركبتهمــا ‪ ،‬وقـ َـر َرت توجيــه التهمــة القويــة عليــه بذلــك‬\n      ‫وتعزيــره بســجنه أربعــة أشــهر مــن تاريــخ إيقافــه وجلــده ثالثــون جلــدة‬\n      ‫كمــت ‪ ،‬قنــع املدعــى عليــه باحلكــم بينمــا اعتــرض‬    ‫دفعــة واحــدة وبــه َح َ‬\n      ‫املدعــي العــام بالئحــة وأفهــم بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن‬\n                                                              ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬رئيــس احملكمــة اجلزئيــة‬\n      ‫بســكاكا املســاعد ففــي هــذا اليــوم األربعــاء املوافــق ‪1433/12/29‬هـ‬\n      ‫الســاعة العاشــرة والنصــف افتتحــت اجللســة وفيهــا قــدم املدعــي العــام‬\n      ‫دعــوى عامــة ضــد املدعــى عليــه ‪ ...........‬ســعودي اجلنســية بالســجل‬\n      ‫ا فيهــا أنــه بتاريــخ ‪1433/11/3‬ه ـ وأثنــاء‬       ‫املدنــي رقــم ‪ ..............‬قائ ـ ً‬\n      ‫قيــام دوريتــن تابعتــن لقــوة املهمــات والواجبــات اخلاصــة بعملهمــا‬\n      ‫مبدينــة ســكاكا مت مشــاهدة املدعــى عليــه علــى ســيارة ‪ .......‬لوحــة‬\n      ‫رقــم (‪ ).......‬يحمــل كشــاف وأثنــاء اســتيقافه قــام بصــدم ســيارتي‬\n      ‫الدوريــات ثــم دخــل مزرعــة مجــاورة وبعــد ذلــك نــزل مــن ســيارته والذ‬\n      ‫بالفــرار ومبعاينــة الســيارة األولــى للدوريــات مــن نــوع ‪ ..........‬لوحــة رقــم‬\n      ‫( ‪ ) ..........‬اتضــح وجــود صدمــة بســيطة علــى البــاب األميــن للراكــب‬\n      ‫ومبعاينــة الســيارة الثانيــة للدوريــات مــن نــوع ‪ .......‬لوحــة رقــم ( ‪.........‬‬\n\n‫‪189‬‬\n\f‫) اتضــح وجــود صدمــة بســيطة علــى الصــدام األمامــي مــن الزاويــة‬\n‫اليمنــى أوقــف املذكــور اســتناد ًا للقــرار الــوزاري ‪ 1900‬وباســتجوابه‬\n‫اعتــرف بهروبــه مــن الدوريــة األمنيــة وأن الســيارة تعــود لــه وأقــر بأنهــم‬\n‫طلبــوا منــه الوقــوف فقــام بالهــرب وحصــل احلــادث وقــد قــدرت التلفيــات‬\n‫الواقعــة علــى ســيارة الدوريــة األمنيــة األولــى والتــي حتمــل اللوحــة رقــم (‬\n‫‪ )..........‬مببلــغ ‪ 700‬ســبعمئة ريــال والســيارة الثانيــة والتــي حتمــل اللوحــة‬\n‫رقــم ( ‪ ) ..........‬مببلغ‪1000‬ألــف ريــال وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام ل ـ ‪ ............ /‬باالعتــداء علــى رجــال األمــن وذلــك باإلضــرار‬\n‫مبركبتيهمــا األولــى مــن نــوع ‪ ......‬لوحــة رقــم (‪ )......‬والثانيــة مــن نــوع‬\n‫‪ ........‬لوحــة رقــم ( ‪ ) ........‬وحيــث أن مــا أقــدم عليــه املذكــور وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ممــا‬\n‫يتعــن معــه إحالتــه للمحكمــة اجلزئيــة وفقـ ًا لنــص املادتــن (‪)128.126‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة فإننــي أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة زاجــرة لــه ورادعــة لغيــره علمـ ًا بــأن احلــق‬\n‫اخلــاص الزال قائم ـاً‪ .‬هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه ضــدي‬          ‫املدعــى عليــه أجــاب قائ ـ ً‬\n‫غيــر صحيــح فلــم أقــم باالعتــداء علــى رجــال األمــن وإمنــا قمــت بصــدم‬\n‫مركبتــي الدوريــة دون قصــد وإمنــا حــادث مــروري عــادي هكــذا أجــاب‬\n‫ا الصحيــح مــا ذكرتــه وبينتــي‬       ‫وبعرضهــا علــى املدعــي العــام قــرر قائ ـ ً‬\n                                                                        ‫عليه ما يلي ‪:‬‬\n‫‪ -1‬اعترافــه بالهــروب مــن الدوريــة األمنيــة واملــدون علــى الصفحــة رقــم‬\n        ‫(‪ )2‬مــن ملــف التحقيــق لفــة رقــم ( ‪ )13‬ممــا يــدل علــى ســوء نيتــه ‪.‬‬\n                   ‫‪ -2‬ما جاء مبحضر تنفيذ املهمة رقم ( ‪ )727‬لفة رقم(‪.)2‬‬\n\n\n                                                                                          ‫‪190‬‬\n\f      ‫‪ -3‬محضــر إثبــات حالــة الســيارتني املتضررتــن املــدون علــى الصفحــة‬\n      ‫رقــم (‪ )6‬مــن ملــف إجــراءات االســتدالل لفــة رقــم (‪ )1‬اطلــب الرجــوع‬\n      ‫إليهــا هكــذا قــرر وبالرجــوع إليهــا وجدتهــا مطابقــة ملــا ذكــره املدعــي‬\n      ‫ا مــا جــاء باعتــرايف فصحيح‬     ‫العــام ومبواجهــة املدعــى عليــه بهــا قــرر قائـ ً‬\n      ‫وأمــا مــا ورد مبحضــر تنفيــذ املهمــة املشــار إليــه فصحيــح ولكــن الصدم‬\n      ‫كان مــن غيــر قصــد وامــا مــا ورد يف إثبــات حالــة الســيارتني فصحيــح‬\n      ‫ا الصحيــح مــا‬    ‫هكــذا قــرر وبعرضــه علــى املدعــي العــام قــرر قائ ـ ً‬\n      ‫ذكرتــه هكــذا قــرر ورفعــت اجللســة للتأمــل إلــى يــوم الســبت املوافــق‬\n      ‫‪1434/3/14‬ه ـ الســاعة العاشــرة والنصــف‪ .‬وبــاهلل التوفيــق و يف جلســة‬\n      ‫أخــرى ففــي يــوم الســبت املوافــق ‪1434/03/14‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة العاشــرة و النصــف وفيهــا حضــر املدعــي العــام و املدعــى عليــه‬\n      ‫و أقفلــت املرافعــة و بعــد ســماع الدعــوى و اإلجابــة و االطــاع علــى أوراق‬\n      ‫املعاملــة و إلنــكار املدعــى عليــه دعــوى املدعــي العــام بقيامــه باالعتــداء‬\n      ‫علــى رجــال األمــن وذلــك باإلضــرار مبركبتيهمــا األولــى مــن نــوع‪......‬‬\n      ‫لوحة رقم (‪ ).......‬والثانية من نوع ‪ .......‬لوحة رقم ( ‪ ) .....‬و إلقرار املدعى‬\n      ‫عليــه بصــدم مركبتــي الدوريــة الرســمية مــن غيــر قصــد و لعــدم وجــود‬\n      ‫بينــة كافيــة لــدى املدعــي العــام إلدانــة املدعــى عليــه مبــا نســب إليــه‬\n      ‫مــن االعتــداء علــى رجــال األمــن و جلميــع مــا تقــدم بــه املدعــي العــام مــن‬\n      ‫أدلــة و قرائــن و لوجــود ســابقة إطــاق نــار مســجلة علــى املدعــى عليــه يف‬\n      ‫‪1431/10/09‬ه ـ حســب الئحــة دعــوى املدعــي العــام لذلــك كلــه و بناء ًا‬\n      ‫عليــه لــم يثبــت لــدي إدانــة املدعــى عليــه املواطــن ‪ .......... /‬باالعتــداء علــى‬\n      ‫رجــال األمــن وذلــك باإلضــرار مبركبتيهمــا األولــى مــن نــوع ‪ .....‬لوحــة‬\n      ‫رقــم (‪ ).....‬والثانيــة مــن نــوع ‪ .....‬لوحــة رقــم (‪ ).....‬و توجهــت التهمــة القويــة‬\n\n\n‫‪191‬‬\n\f‫عليــه بذلــك و قــررت تعزيــره لقــاء ذلــك بســجنه مــدة أربعــة أشــهر تبــدأ‬\n‫اعتبــار ًا مــن تاريــخ إيقافــه يحتســب منهــا مــا أمضــاه موقوفـ ًا يف ذمــة هــذه‬\n‫القضيــة و جلــدة ثالثــون جلــدة دفعــة واحــدة هــذا مــا حكمـ ُـت بــه و تلــى‬\n‫عليهمــا فقنــع بــه املدعــى عليــه دون املدعــي العــام و طلــب متييــزه و أســتعد‬\n‫بتقــدمي الئحــة اعتراضيــة عليــه و قــرر فهمــه بتعليمــات التمييــز و أفهمتــه‬\n‫بــأن عليــه احلضــور لهــذه احملكمــة يــوم االثنــن ‪1434/03/16‬ه ـ‬\n‫الســاعة الثامنــة ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/14‬ه ـ الســاعة‬\n                                                                  ‫احلاديــة عشــرة‪.‬‬\n\n\n\n\n                                                                                         ‫‪192‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":188,"source_page_end":192,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aecd03eec6a48fdc3a59508c3e5cb6a5367d8ac5200d8487e097b865cb16fbe4","normalized_text_hash":"aab86e55bcfc8d14fc93fa0adcc6e32d9e2e2efe2c6dabd59818733c2c30246c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p188-3463079"},{"id":"d6129871-1f76-5a5a-bd14-a518dfe85223","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -إقامه الدعوى العامة يف ضرب الزوج لزوجته مع تنازل الزوجة عن حقها اخلاص -من أسباب تخفيف العقوبة يف احلق العام تنازل املدعي اخلاص عن حقه -االكتفاء بالتعزير بأخذ التعهد تعميم معالي وزير العدل رقم /8ت 21/يف 1411/2/15ه -1 املتضمن عدم إقامة دعوى عامة أمام المحاكم يف املشادات والتماسك باأليدي أو املضاربات البسيطة التي تقتصر على","document_number":"34224565","case_number":"33689550","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/27","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -إقامه الدعوى العامة يف ضرب الزوج لزوجته مع تنازل الزوجة عن حقها اخلاص -من أسباب تخفيف العقوبة يف احلق العام تنازل املدعي اخلاص عن حقه -االكتفاء بالتعزير بأخذ التعهد تعميم معالي وزير العدل رقم /8ت 21/يف 1411/2/15ه -1 املتضمن عدم إقامة دعوى عامة أمام المحاكم يف املشادات والتماسك باأليدي أو املضاربات البسيطة التي تقتصر على","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34224565:‬تاريخه‪1434/5/27 :‬هـ‬\n                         ‫رقم الدعوى‪33689550:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34250879‬تاريخه‪1434/7/4 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬إقامــه الدعــوى العامــة يف‬\n      ‫ضــرب الــزوج لزوجتــه مــع تنــازل الزوجــة عــن حقهــا اخلــاص ‪ -‬مــن‬\n      ‫أســباب تخفيــف العقوبــة يف احلــق العــام تنــازل املدعــي اخلــاص عــن‬\n                                  ‫حقــه ‪ -‬االكتفــاء بالتعزيــر بأخــذ التعهــد‬\n\n\n\n\n      ‫تعميــم معالــي وزيــر العــدل رقــم ‪/8‬ت‪ 21/‬يف ‪1411/2/15‬ه ـ‬                ‫‪-1‬‬\n      ‫املتضمــن عــدم إقامــة دعــوى عامــة أمــام احملاكــم يف املشــادات‬\n      ‫والتماســك باأليــدي أو املضاربــات البســيطة التــي تقتصــر علــى‬\n      ‫إصابــات ال يزيــد التعطيــل فيهــا عــن العمــل أكثــر مــن عشــرة أيــام‬\n      ‫حســب التقريــر الطبــي طاملــا تنــازل املصــاب عــن شــكواه ولــم تشــكل‬\n      ‫املضاربــة إخــاال باألمــن مــع أخــذ التعهــد علــى الطرفــن بعــدم العــودة‬\n                                                                          ‫لذ لــك‪.‬‬\n      ‫قولــه صاحــب شــرح منتهــى االرادات|‪ « :‬ولــه ‪ -‬أي‪ :‬الــزوج واألب‬         ‫‪-2‬‬\n      ‫والســيد ‪ -‬تأديــب زوجــة وتأديــب ولــد لــو كان الولــد مكلف ـ ًا مزوج ـ ًا‬\n                                               ‫بضــرب غيــر مبــرح » ( ‪.)686 /5‬‬\n\n\n\n\n‫‪193‬‬\n\f‫جــرى توجيــه االتهــام للمدعــى عليــه بقيامــه باإلعتــداء علــى زوجتــه‬\n‫بالضرب بيده وجتاوز حد التأديب الشــرعي والتســبب يف جرح تهتكي‬\n‫داخــل الشــفة الســفلى مــع فقــد جــزء مــن إحــدى األســنان ‪ ،‬وطلــب إثبــات‬\n‫مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة عليــه‪ ،‬أقــر املدعــى عليــه‬\n‫بالتهمــة ودفــع بأنهــا التــي جعلتــه يقــوم بهــذا الفعــل لعنادهــا لــه وتســببها‬\n‫يف املشــاكل وقــد تنازلــت عــن حقهــا اخلــاص‪ ،‬جــرى االطــاع علــى‬\n‫ـاء علــى دعــوى املدعــي‬\n                        ‫التقريــر الطبــي وعلــى محضــر تنــازل الزوجــة‪ ،‬بنـ ً‬\n‫العــام وإجابــة املدعــى عليــه ولتنــازل املدعيــة عــن حقهــا اخلــاص وبنــاء‬\n‫علــى تعميــم معالــي املتضمــن عــدم إقامــة دعــوى عامــة أمــام احملاكــم‬\n‫يف املشــادات والتماســك باأليــدي أو التعــدي بالضــرب البســيط الــذي‬\n‫يقتصــر علــى إصابــات ال يزيــد التعطيــل فيهــا عــن العمــل أكثــر مــن‬\n‫عشــرة أيــام حســب التقريــر الطبــي طاملــا تنــازل املصــاب عــن شــكواه‬\n‫ولــم تشــكل املضاربــة إخــاال باألمــن مــع أخــذ التعهــد علــى الطرفــن‬\n‫بعــدم العــودة لذلــك ‪ ،‬وتطلعــا الســتدامة العشــرة الزوجيــة بينهمــا ‪ ،‬وألن‬\n‫املدعــى عليــه جتــاوز احلــد الشــرعي يف الضــرب ‪ ،‬لذلــك كلــه فقــد ثبــت‬\n‫لــدى احملكمــة إدانــة املدعــى عليــه باالعتــداء علــى زوجتــه بالضــرب‬\n‫بيــده وجتــاوزه حــد التأديــب الشــرعي والتســبب يف اإلصابــة املوصوفــة‬\n‫بالتقريــر الطبــي وتهديدهــا وقــررت اإلكتفــاء بأخــذ التعهــد عليــه بعــدم‬\n‫العــودة ملــا بــدر منــه‪ ،‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة بينمــا اعتــرض املدعــي العــام بــدون الئحــة مكتفيــا بالئحــة‬\n                      ‫الدعــوى‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n                                                                                         ‫‪194‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n      ‫‪........‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n      ‫وتاريــخ ‪1433/12/19‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالدمــام برقــم وتاريــخ ‪1433/12/19‬ه ـ افتتحــت اجللســة يف‬\n      ‫يــوم الثالثــاء ‪1434/5/21‬ه ـ الســاعة احلاديــة عشــرة وفيهــا قــدم املدعــي‬\n      ‫العــام ‪ ........‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء‬\n      ‫العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪........ /‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )........‬حيــث إنــه بتاريــخ ‪1433/10/10‬ه ـ‬\n      ‫تقدمــت املواطنــة‪........ /‬ملركــز شــرطة شــمال الدمــام مدعيـ ًة تعرضهــا‬\n      ‫لالعتــداء بالضــرب مــن قبــل زوجهــا املدعــى عليــه بســبب خــاف‬\n      ‫عائلــي حــدث بينهمــا حيــث قــام املدعــى عليــه بضربهــا ممــا تســبب لهــا‬\n      ‫بكســر أحــد أســنانها وخلخلــة بعضهــا وقــد صــدر بحــق املجنــي عليــه‬\n      ‫التقريــر طبــي النهائــي الصــادر مــن مجمــع الدمــام الطبــي رقــم ‪........‬‬\n      ‫وتاريــخ ‪1433/10/4‬ه ـ املتضمــن أنــه بالكشــف علــى املذكــورة بتاريخ‬\n      ‫‪1433/9/19‬ه ـ وجــدت مصابــة بجــرح تهتكــي علــى داخــل الشــفة‬\n      ‫الســفلية مــع فقــد للســن الســفلي اثــر ادعــاء اعتــداء مت عمــل الــازم‬\n      ‫ومــدة الشــفاء عشــرة أيــام للجــروح مــا لــم حتــدث مضاعفــات أمــا مــدة‬\n      ‫الشــفاء لفقــد الســن ال يوجــد مــدة شــفاء وباالطــاع علــى محضــر تفريــغ‬\n      ‫الرســائل‪ :‬جــاء يف الرســالة األولــى مــا نصــه ( لــو أشــوفك علــي احلــال‬\n      ‫ألذبحــك أنتــي وأبــوك ) وبســماع أقــوال املدعــى عليــه األوليــة ‪ :‬أقــر‬\n\n‫‪195‬‬\n\f‫بضــرب زوجتــه بواســطة يــده بســبب خــاف عائلي وبإرســال عدة رســائل‬\n‫لهــا وباســتجواب املدعــى عليــه‪ :‬أقــر بقيامــة بضــرب زوجتــه بواســطة‬\n‫يــده وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه باالعتــداء‬\n‫علــى زوجتــه بالضــرب بواســطة يــده وجتــاوز حــد التأديــب الشــرعي‬\n‫والتســبب لهــا باإلصابــة املوصوفــة يف التقريــر الطبــي وتهديدهــا وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء يف إقــراره مبحضــر االســتجواب‬\n‫املنــوه عنــه واملرفــق علــى اللفــة رقــم (‪ )12-11‬وبســماع األقــوال املــدون‬\n‫علــى الصفحــة رقــم (‪ )14/13‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد‬\n‫لفــه رقــم (‪ -2 )1‬مــا جــاء يف التقريــر الطبــي للمجنــي عليهــا املنــوه عنــه‬\n‫واملرفــق علــى اللفــة رقــم (‪ -3 )13‬مــا جــاء يف محضــر تفريــغ رســائل‬\n‫اجلــوال املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )12‬مــن ملــف تقريــر‬\n‫األحــوال األمنيــة املوحــد لفــه رقــم (‪ )1‬وبالبحــث عــن ســوابقه لــم يعثــر‬\n‫لــه علــى ســوابق وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره هكــذا ادعــى‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام‬\n‫صحيــح لكنهــا هــي التــي جعلتنــي أقــوم بضربهــا بيــدي علــى وجههــا‬\n‫كونهــا حتــب العنــاد وتســبب املشــاكل وقــد تنازلــت عــن حقهــا اخلــاص‬\n‫هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال‬\n‫بينتــي مــا جــاء يف أوراق املعاملــة ثــم جــرى اإلطــاع علــى أوراق املعاملــة‬\n‫فوجــدت علــى لفــة رقــم (‪ )15‬تقريــر ًا طبي ـ ًا صــادر ًا مــن مجمــع الدمــام‬\n‫الطبــي برقــم ‪ 17844‬وتاريــخ ‪1433/10/4‬ه ـ املتضمــن طبــق مــا ذكــر‬\n‫املدعــي العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )23‬تنــازل مــن‬\n\n\n                                                                                       ‫‪196‬‬\n\f      ‫املدعيــة عــن حقهــا اخلــاص فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n      ‫العــام وإجابــة املدعــى عليــه ومبــا أن املدعيــة باحلــق اخلــاص قــد تنازلــت‬\n      ‫عــن دعواهــا حســب اإلقــرار املرفــق باملعاملــة وبنــاء علــى تعميــم معالــي‬\n      ‫وزيــر العــدل رقــم ‪/8‬ت‪ 21/‬يف ‪1411/2/15‬ه ـ املتضمــن عــدم إقامــة‬\n      ‫دعــوى احلــق العــام أمــام احملاكــم يف املشــادات والتماســك باأليــدي أو‬\n      ‫املضاربــات البســيطة التــي تقتصــر علــى إصابــات ال يزيــد التعطيــل فيهــا‬\n      ‫العمــل أكثــر مــن عشــرة أيــام حســب تقديــر التقريــر الطبــي طاملــا تنــازل‬\n      ‫املصــاب عــن شــكواه ولــم تشــكل املضاربــة إخــال باألمــن مــع أخــذ‬\n      ‫التعهــد علــى الطرفــن بعــدم العــودة لذلــك ونظــر ًا الســتدامة العشــرة‬\n      ‫الزوجيــة بينهمــا ومبــا أن املدعــى عليــه جتــاوز احلــد يف الضــرب فقــد‬\n      ‫[و َلـ ُه ) َأ ْي‬ ‫ذكــر يف شــرح منتهــى اإلرادات (ج ‪ / 10‬ص ‪)254‬مــا نصــه‪َ :‬‬\n      ‫ان ا ْل َو َلـ ُـد‬\n                      ‫ك َ‬ ‫السـ ِّـيدِ ( َت ْأ ِديـ ُـب َز ْو َجـ ٍة َو ) َت ْأ ِديـ ُـب ( َو َلــدٍ َو َلـ ْـو ) َ‬      ‫الـ َّـز ْو ِج َو ْ َ‬\n                                                                                                               ‫ال ِب َو َّ‬\n      ‫كل ًَّفــا ُم َز َّو ًجــا ِب َضـ ْـر ٍب غَ ْيـ ِـر ُم َبـ ِّـر ٍح] َولــذا كلــه فقــد ثبــت لــدي إدانــة‬                ‫( ُم َ‬\n      ‫املدعــى عليــه باالعتــداء علــى زوجتــه بالضــرب بواســطة يــده وجتــاوز حــد‬\n      ‫التأديــب الشــرعي والتســبب لهــا باإلصابــة املوصوفــة يف التقريــر الطبــي‬\n      ‫وتهديدهــا وقــررت االكتفــاء بأخــذ التعهــد علــى املدعــى عليــه بعــدم‬\n      ‫العــودة ملــا بــدر منــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n      ‫القناعــة باحلكــم كمــا قــرر املدعــي العــام االعتــراض علــى احلكــم‬\n      ‫وطلــب االســتئناف مكتفي ـ ًا بالئحــة الدعــوى العامــة وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/05/27‬ه ــاحلمد‬\n      ‫هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/07/08‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الثامنــة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية برقــم ‪ 341612885‬يف ‪1434/07/04‬ه ــوبرفقها‬\n\n\n‫‪197‬‬\n\f‫القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم ‪ 34250879‬يف‬\n‫‪1434/06/25‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                           ‫‪1434/07/08‬ه ـ‬\n\n\n\n\n                                                                                ‫‪198‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":193,"source_page_end":198,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c448a789b814a6dee81ad1c9926555e010bb722e05c4f58589460d0c2c810535","normalized_text_hash":"51bb66fa0c29f4b7128e2310d559e29fcf04a47eb8bc17f068507b16c3c0dede","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p193-34224565"},{"id":"2ba3ecc2-d698-5740-bfea-9544360801cb","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -حيازة ساح ناري بدون ترخيص -إطاق أعيرة نارية - انتهاك حرمة منزل -مقاومة قوات الشرطة -وجود سوابق قضائية -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملثل ذلك .","document_number":"344920","case_number":"33690236","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"اعتداء -حيازة ساح ناري بدون ترخيص -إطاق أعيرة نارية - انتهاك حرمة منزل -مقاومة قوات الشرطة -وجود سوابق قضائية -تعزير بالسجن واجللد وأخذ تعهد بعدم العودة ملثل ذلك .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 344920 :‬تاريخه‪1434/1/26 :‬هـ‬\n                         ‫رقم الدعوى‪33690236:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34183490‬تاريخه‪1434/4/9 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬حيــازة ســاح نــاري بــدون ترخيــص ‪ -‬إطــاق أعيــرة ناريــة ‪-‬‬\n      ‫انتهــاك حرمــة منــزل ‪ -‬مقاومــة قــوات الشــرطة ‪ -‬وجود ســوابق قضائية‬\n            ‫‪ -‬تعزيــر بالســجن واجللــد وأخــذ تعهــد بعــدم العــودة ملثــل ذلــك ‪.‬‬\n\n\n\n\n                                          ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العــام ‪ ،‬للمدعــى عليــه ‪ ،‬بإشــهار‬\n      ‫الســاح علــى مواطــن ‪ ،‬بقصــد التهديد ومقاومــة رجل األمن‪ ،‬واالعتداء‬\n      ‫علــى مركبتــه بالصــدم والهــروب منــه ‪ ،‬وصــدم ســيارة مواطــن عمــدا‬\n      ‫وانتهــاك حرمــة منــزل ‪ ،‬ويطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بعقوبــة تعزيريــة حيــث تقــدم املعتــدى عليــه بشــكوى ضــد املدعــى عليــه‬\n      ‫بقيامــه بإطــاق النــار عليــه ‪ ،‬وملــا حاولــت الدوريــة إيقافــه صدم ســيارتها‬\n      ‫والذ بالفــرار ودخــل منــزل مواطــن مــن غيــر إذنــه فجــرى محاصــرة املنــزل‬\n      ‫حتــى مت القبــض عليــه وبتفتيــش الســيارة عثــر بحوزتــه علــى ســاح نــاري‬\n      ‫‪ ،‬أقــر املدعــى عليــه قيامــه بإشــهار الســاح علــى مواطــن بقصــد التهديد‬\n      ‫ومقاومــة رجــال األمــن واالعتــداء علــى مركبتــه بالصــدم والهــروب‬\n      ‫وصــدم ســيارة أحــد املواطنــن عمــدا ودخولــه إلــى منــزل واســتراحة‬\n‫‪199‬‬\n\f‫غيــره مــن غيــر إذنــه وأنــه ال يعــرف املجنــي عليــه وإمنــا قــام بذلــك لوجــود‬\n‫خــاف بينهمــا أثنــاء ســيرهما بالســيارة ولــم يثبــت قيامــه بإطــاق النــار‬\n‫‪ ،‬أقــر املدعــى عليــه بــأن لــه ســوابق قضائيــة ‪ ،‬وإلقــرار املدعــى عليــه‬\n‫بإشــهاره ســاحا وانتهاكــه حرمــة منــزل وإخافــة الســاكنني ولتعــدد‬\n‫ســوابق املدعــى عليــه ممــا يــدل علــى ســوء ســلوكه وعــدم ارتداعــه‬\n‫ولتعريضــه نفســه واآلخريــن للخطــر بصدمــه لســيارة الدوريــة وســيارة‬\n‫أحــد املواطنــن لــذا فقــد قــررت احملكمــة ثبــوت إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه يف الدعــوى وقـ َـررت تعزيــره بســجنه ســنة كاملــة مــن‬\n‫تاريــخ إيقافــه وجلــده مئتــن وخمســن جلــدة مفرقــة علــى خمــس دفعــات‬\n‫متســاوية بــن كل دفعــة والتــي تليهــا عشــرة أيــام مــع أخــذ التعهــد عليــه‬\n‫بعــدم العــودة ملثــل ذلــك‪ ،‬قــرر الطرفــان عــدم القناعــة‪ ،‬صــدق احلكــم‬\n                                                      ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد وحــده وبعــد فلــدي أنــا ‪ ..............‬رئيــس احملكمــة اجلزائيــة‬\n‫بســكاكا وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 33690236‬وتاريــخ‬\n‫‪1433/12/19‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 332180988‬وتاريــخ‬\n‫‪1433/12/19‬ه ـ ففــي هــذا اليــوم الثالثــاء املوافــق ‪1433/12/06‬ه ـ‬\n‫افتتحــت اجللســة األولــى يف متــام الســاعة ‪ 08:00‬وفيهــا قــدم املدعــي العــام‬\n‫‪ ...........‬الئحــة دعــوى عامــة ضــد ‪ .................‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ ...............‬قائــا فيهــا إنــه بتاريــخ ‪1433/11/21‬ه ـ تقــدم املواطــن‬\n‫‪ ...........‬بدعــوى ملركــز شــرطة ‪ ........‬مفادهــا أنــه أثنــاء ســيره علــى‬\n‫ســيارته نــوع ‪ ........‬موديــل ‪ ......‬حتمــل اللوحــة رقــم (‪ )........‬برفقــة شــقيقه‬\n\n                                                                                          ‫‪200‬‬\n\f      ‫‪ ...... /‬الحــظ ســيارة تســير خلفــه مــن نــوع ‪ ........‬موديــل ‪ ......‬حتمل اللوحة‬\n      ‫رقــم (‪ )......‬وعنــد توقفــه عنــد إشــارة تقاطــع طريــق امللــك عبدالعزيــز‬\n      ‫بالقــرب مــن مطعــم ‪ .....‬توقــف املتهــم املذكــور خلفــه ونــزل شــقيقه ‪....‬‬\n      ‫إلــى البقالــة فقــام املتهــم املذكــور بإطــاق النــار باجتــاه شــقيقه طلقــة‬\n      ‫واحــدة ثــم الذ بالفــرار وأنــه قــام بإبــاغ الدوريــات األمنيــة وأنــه ال يعــرف‬\n      ‫املذكــور‪ .‬وورد يف محضــر تنفيــذ املهمــة رقــم (‪ )6407‬بأنــه اســتوقف‬\n      ‫املدعــي الدوريــة وأفــاد بأنــه تعــرض إلطــاق نــار ومت متابعــة املتهــم‬\n      ‫املذكــور حتــى قــام بعكــس الســير علــى الطريــق اإلقليمــي باجتــاه‬\n      ‫الشــمال وارتطــم بالدوريــة مــن األمــام ثــم ارتكــب الفــرار علــى األقــدام‬\n      ‫ودخــل منــزل املدعــو ‪ ....... /‬ومت محاصــرة املنــزل مــن جميــع اجلهــات ومت‬\n      ‫القبــض عليــه وبتفتيــش ســيارة املتهــم نــوع ‪ .......‬حتمــل اللوحــة رقــم (‪)......‬‬\n      ‫عثــر علــى الســاح بذخيرتــه‪ .‬وورد يف محضــر االنتقــال واملعاينــة بــأن‬\n      ‫موقــع بدايــة احلادثــة يقــع يف طريــق امللــك عبدالعزيــز بالقــرب مــن مطعــم‬\n      ‫‪ .....‬والــذي يقــع بحــي ‪ ........‬وجــرى مســح املوقــع برفقــة اجلهــات املختصــة‬\n      ‫ولــم يعثــر علــى فــوارغ إطــاق نــار أو آثــار مقــذوف نــاري ‪ ،‬ومت مســائلة‬\n      ‫أصحــاب احملــات املجــاورة للموقــع فلــم يوجــد مــن يثبــت ســماع صــوت‬\n      ‫إطــاق النــار ومت االنتقــال ملوقــع حــادث صــدم الدوريــة واتضــح بأنــه يقــع‬\n      ‫علــى تقاطــع طريــق ‪( ...................‬الطريــق اإلقليمــي) مــع طريــق شــارع‬\n      ‫العــرب واتضــح أنــه يوجــد بهــا صــدم مــن اجلانب األيســر مبقدمة الســيارة‬\n      ‫وصــدم يف البــاب األميــن‪ .‬ومت عــرض املتهــم املذكــور ومرافقــه (‪)............‬‬\n      ‫صــدر بحقــه أمــر حفــظ دعــوى رقــم ‪ 20460‬وتاريــخ ‪1433/12/04‬هــ)‬\n      ‫وســيارة نــوع ‪ ........‬موديــل ‪ ......‬حتمــل اللوحــة رقــم (‪ ).....‬علــى املدعــي ‪/‬‬\n      ‫‪ .........‬وشــقيقه ‪ .....‬ومتكنــا مــن التعــرف عليهمــا وأنهمــا كانــا يســتقالن‬\n\n\n‫‪201‬‬\n\f‫الســيارة وأن املتهــم املذكــور هــو مــن قــام بإطــاق النــار‪ .‬وورد خطــاب‬\n‫مديــر إدارة دوريــات األمــن بــأن التلفيــات التــي حلقــت باملركبــة تقــدر‬\n‫مببلــغ (‪ )6720‬ريــال‪ .‬وبضبــط إفــادة املواطــن ‪ ....... /‬أفــاد بأنــه أثنــاء‬\n‫توقفــه عنــد إشــارة تقاطــع شــارع العــرب مــع شــارع األميــر عبداإللــه وإذا‬\n‫بســيارة نــوع ‪ .......‬حتمــل اللوحــة رقــم (‪ ).........‬تســير بســرعة وخلفهــا‬\n‫دوريــات أمنيــة وعنــد انعطــاف صاحــب الســيارة املذكــورة ارتطــم‬\n‫بســيارته ثــم ارتكــب الفــرار‪ .‬أوقــف املذكــور اســتنادا للقــرار الــوزاري‬\n‫‪1900‬وبســماع أقــوال املتهــم املذكــور واســتجوابه أقــر بأنــه قــام بإشــهار‬\n‫الســاح علــى املدعــي ‪ .......... /‬وأقــر بــأن الســاح يعــود لــه وأنــه غيــر‬\n‫مرخــص (مت فــرز أوراق مســتقلة للســاح إلحالتهــا للمحكمــة اإلداريــة)‬\n‫وأنكــر قيامــه بإطــاق النــار وأقــر بأنــه ارتكــب الفــرار حينمــا أراد‬\n‫رجــل األمــن اســتيقافه وأقــر بأنــه قــام بصدم ســيارة مواطن نــوع ‪ .....‬أثناء‬\n‫هروبــه مــن الدوريــة وأن صاحــب الدوريــة قــام بعكــس الســير وصدمــه‬\n‫وأقــر بأنــه قــام بإيقــاف ســيارته والهــروب علــى األقــدام وأنــه قــام بالقفــز‬\n‫يف أحــد املنــازل ودخــول اســتراحة مهجــورة وأنــه مت القبــض عليــه وأفــاد‬\n‫بأنــه ال يعــرف املدعــي وأن ســبب قيامــه بذلــك هــو ســوء تفاهــم حصــل‬\n‫أثنــاء الســير وأن املدعــو ‪ ........ /‬كان مرافــق لــه فقــط‪ .‬وانتهــى التحقيق‬\n‫إلــى توجيــه االتهــام لــ‪ ............ /‬بإشــهار الســاح علــى املواطــن ‪............. /‬‬\n‫بقصــد التهديــد ومقاومــة رجــل األمــن واالعتــداء علــى مركبتــه بالصدم‬\n‫والهــروب منــه وصــدم ســيارة املواطــن ‪ ................ /‬عمــدا وانتهــاك حرمة‬\n‫منــزل واســتراحة‪ .‬وحيــث إن مــا أقــدم عليه املتهــم املذكور وهو بكامل‬\n‫أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ‪ ،‬ممــا يتعــن‬\n‫معــه إحالتــه إلــى احملكمــة اجلزئيــة اســتنادا للمادتــن (‪ 126‬و ‪ )128‬مــن‬\n\n\n                                                                                             ‫‪202‬‬\n\f      ‫نظــام اإلجــراءات اجلزائيــة فإننــي أطلــب إثبــات مــا أســند إليــه ‪ ،‬واحلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره‪ .‬علمــا بــأن احلــق اخلــاص جلميــع‬\n      ‫أطــراف القضيــة مــا زال قائــم‪ .‬هــذه دعــواي وبعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام مــن أننــي‬\n      ‫قمــت بإشــهار الســاح علــى املواطــن ‪ .........‬بقصــد التهديــد ومقاومــة‬\n      ‫رجــل األمــن واالعتــداء علــى مركبتــه بالصــدم والهــروب وصــدم ســيارة‬\n      ‫أحــد املواطنــن عمــدا ودخولــي إلــى منــزل واســتراحة بغيــر إذن صاحبهــا‬\n      ‫فهــذا صحيــح والســبب يف ذلــك أنــه توجــد مشــكلة بينــي وبــن ‪.........‬‬\n      ‫حيــث قــام بعمــل حركــة أثنــاء الســير فغضبــت عليــه وفعلــت مــا ذكــره‬\n      ‫املدعــي العــام هكــذا أجــاب هــذا وقــد جــرى ســؤال املدعــى عليــه عــن‬\n      ‫ســوابقه وهــي ثــاث ســوابق ســابقتان أخالقيتــان وســابقة يف حيــازة‬\n      ‫واســتعمال املخــدرات فقــال إن الســوابق صحيحــة ونلــت اجلــزاء عليهــا‬\n      ‫لــذا وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى‬\n      ‫عليــه علــى دعــوى املدعــي العــام ومؤاخــذة للمدعــى عليــه بإقــراره وحيــث‬\n      ‫إن املدعــى عليــه أشــهر ســاحا قاتــا علــى أحــد املواطنــن مــا يــدل علــى‬\n      ‫اســتخفافه باألنفــس وباألمــن ورجالــه وحيــث إن املدعــى عليــه انتهــك‬\n      ‫حرمــة منــزل أحــد املواطنــن بالدخــول فيــه بغيــر إذن ممــا ســبب الذعــر‬\n      ‫واخلــوف بــن النســاء واألطفــال اآلمنــن ولوجــود عــدة ســوابق علــى‬\n      ‫املدعــى عليــه ممــا يــدل علــى ســوء ســلوكه وعــدم ارتداعــه وحيــث إن‬\n      ‫املدعــى عليــه عــرض نفســه وعــرض اآلخريــن للخطــر بصدمــه للدوريــة‬\n      ‫ولســيارة أحــد املواطنــن لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبــا‬\n      ‫نســب لــه بدعــوى املدعــي العــام وقــررت تعزيــره لقــاء ذلــك وذلــك بســجنه‬\n      ‫ســنة كاملــة مــن تاريــخ إيقافــه وجلــده مئتــن وخمســن جلــدة مفرقــة‬\n\n\n‫‪203‬‬\n\f‫علــى خمــس دفعــات متســاوية بــن كل دفعــة وأخــرى عشــرة أيــام مــع‬\n‫أخــذ التعهــد عليــه بعــدم العــودة ملثــل ذلــك وبذلــك قضيــت وبعــرض ذلــك‬\n‫علــى املدعــى عليــه واملدعــي العــام قــررا عــدم القناعــة وطلبــا االســتئناف‬\n‫فأفهمتهمــا أنــه يف يــوم الســبت القــادم املوافــق ‪1434/01/10‬ه ـ ســوف‬\n‫يســلم كل واحــد منهمــا نســخة مــن احلكــم لالعتــراض عليــه وأن لــكل‬\n‫واحــد منهمــا مــدة نظاميــة وهــي ثالثــون يومــا مــن تاريــخ الســبت القــادم‬\n‫يقــدم كل واحــد منهمــا خاللهــا الئحتــه االعتراضيــة ففهمــا ذلــك‬\n‫وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة التاســعة وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى ســيدنا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪1434/01/06‬ه ـ ‪ ،‬احلمــد هلل وحــده وبعــد فلــدي أنــا ‪............‬‬\n‫رئيــس احملكمــة اجلزائيــة بســكاكا ويف هــذا اليــوم األحــد املوافــق‬\n‫‪1434/02/24‬ه ـ افتتحــت اجللســة الرابعــة يف متــام الســاعة ‪11:30‬‬\n‫وفيهــا حضــر املدعــي العــام وقــرر أنــه يرغــب باالعتــراض علــى احلكــم‬\n‫مــن غيــر تقــدمي الئحــة اعتراضيــة فأجبنــاه لذلــك وعليــه جــرى التوقيــع‬\n‫وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــرة وخمــس وثالثــون دقيقــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وعلــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1434/02/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد مت تصديــق احلكم من محكمة االســتئناف‬\n                                                                 ‫وبــاهلل التوفيق ‪.‬‬\n\n\n\n\n                                                                                      ‫‪204‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":199,"source_page_end":204,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"41d1aac9944a61b45175ca1035911a06021ba0af1c286d3872ab99251a719d85","normalized_text_hash":"4e9e40fc8f4b913741070f40a61e823e77945f33b7842510ca37953f268dd16e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p199-344920"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

